// Assemble the Daliesk Knowledge Graph page from the research JSON files in this directory.
// Inputs (all optional except kg-core.json): kg-existing-papers.json, kg-literature.json, ai-village-facts.json, kg-village-nodes.json, kg-village-extra.json, kg-baselines.json.
import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const dir = dirname(fileURLToPath(import.meta.url))
const read = (name) => (existsSync(join(dir, name)) ? JSON.parse(readFileSync(join(dir, name), 'utf8')) : undefined)
const core = read('kg-core.json')
const existing = read('kg-existing-papers.json') ?? []
const literature = read('kg-literature.json') ?? {}
const village = read('kg-village-nodes.json') ?? { nodes: [], edges: [] }

const nodes = new Map()
const edges = []
const addNode = (n) => { if (!n.id) return; const prev = nodes.get(n.id); nodes.set(n.id, prev ? { ...prev, ...n, themes: [...new Set([...(prev.themes || []), ...(n.themes || [])])], workflows: [...new Set([...(prev.workflows || []), ...(n.workflows || [])])], principles: [...new Set([...(prev.principles || []), ...(n.principles || [])])] } : n) }
const addEdge = (from, to, label) => { if (from && to && from !== to) edges.push({ from, to, label: label || 'related' }) }

for (const w of core.workflows) addNode({ id: w.id, type: 'workflow', title: w.title, summary: w.summary, source: 'daliesk' })
for (const p of core.principles) addNode({ id: p.id, type: 'principle', title: p.title, summary: p.summary, source: 'daliesk' })
for (const p of core.packages) { addNode({ id: p.id, type: 'package', title: p.title, summary: p.summary, url: p.url, workflows: p.workflows, principles: p.principles, source: 'daliesk' }); for (const w of p.workflows) addEdge(p.id, w, 'serves'); for (const pr of p.principles) addEdge(p.id, pr, 'enforces') }

const themeOf = {}
for (const [theme, ids] of Object.entries(core.existingPaperThemes)) for (const id of ids) themeOf[id] = theme
for (const p of existing) {
  const theme = themeOf[p.id]
  addNode({ id: p.id, type: 'paper', title: p.title || p.anchor || p.id, subtitle: p.firstAuthor ? `${p.firstAuthor} et al.` : undefined, year: p.published, summary: p.summary, url: p.url, themes: theme ? [theme] : [], workflows: theme ? core.existingPaperWorkflows[theme] : [], source: p.sources.includes('Self-verifying harness') ? 'self-verifying-harness' : 'field-study' })
  for (const w of (theme ? core.existingPaperWorkflows[theme] : [])) addEdge(p.id, w, 'informs')
}
for (const [a, b, label] of core.existingPaperEdges) addEdge(a, b, label)
for (const [a, b, label] of core.packagePaperEdges) addEdge(a, b, label)

// Literature agent output: { papers: [{ arxiv_id | id, title, first_author | firstAuthor, year_month | yearMonth, claim, result, relevance: string[] of W/P tags | object | string, themes?, edges: [{ target | to, label }] }], projects: [{ name, description, url, type? }] }
const THEME_OF_PROJECT = { 'ai-village': 'ai-village' }
const litIds = new Set()
for (const raw of literature.papers || []) {
  const p = { id: raw.id || raw.arxiv_id, title: raw.title, firstAuthor: raw.firstAuthor || raw.first_author, yearMonth: raw.yearMonth || raw.year_month || raw.year, claim: raw.claim || raw.summary, result: raw.result, relevance: raw.relevance, themes: raw.themes || raw.theme && [raw.theme] || [], edges: raw.edges || [] }
  if (!p.id) continue
  litIds.add(p.id)
  const rel = p.relevance
  const tags = Array.isArray(rel) ? rel : rel && typeof rel === 'object' ? Object.keys(rel) : []
  const workflows = Array.isArray(raw.workflows) ? raw.workflows : tags.filter(k => /^W\d$/.test(k))
  const principles = Array.isArray(raw.principles) ? raw.principles : tags.filter(k => /^P\d$/.test(k))
  const relevance = typeof rel === 'string' ? rel : rel && !Array.isArray(rel) && typeof rel === 'object' ? Object.entries(rel).map(([k, v]) => `${k}: ${v}`).join(' ') : raw.relevance_note || raw.why || undefined
  addNode({ id: p.id, type: 'paper', title: p.title, subtitle: p.firstAuthor ? `${p.firstAuthor} et al.` : undefined, year: p.yearMonth, summary: p.claim, result: p.result, relevance, url: raw.url || `https://arxiv.org/abs/${p.id}`, themes: [...p.themes, 'long-running-agents'], workflows, principles, source: 'literature' })
  for (const w of workflows) addEdge(p.id, w, 'informs')
  for (const pr of principles) addEdge(p.id, pr, 'supports')
  for (const e of p.edges) addEdge(p.id, typeof e === 'string' ? e : (e.to || e.target || e.id), typeof e === 'string' ? 'related' : (e.label || 'related'))
}
const projectId = (name) => `project:${String(name || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}`
for (const pr of literature.projects || []) {
  const name = pr.name || pr.title
  let id = pr.id || projectId(name)
  if (/ai.village/i.test(name)) id = 'project:ai-village'
  addNode({ id, type: pr.type || 'project', title: name, summary: pr.description, url: pr.url, themes: pr.themes || [THEME_OF_PROJECT[id] || 'long-running-agents'], workflows: pr.workflows || [], source: id === 'project:ai-village' ? 'ai-village' : 'literature' })
  for (const e of pr.edges || []) addEdge(id, typeof e === 'string' ? e : (e.to || e.target), typeof e === 'string' ? 'related' : (e.label || 'related'))
}
// Edges from literature papers to projects named in edge targets by project name (the agent used names or ids).
for (const e of edges) { if (!/^\d{4}\.\d{4,5}$/.test(e.to) && !nodes.has(e.to) && !/^(W|P)\d$/.test(e.to) && !e.to.includes(':')) { const cand = projectId(e.to); if (nodes.has(cand)) e.to = cand; if (/ai.village/i.test(e.to)) e.to = 'project:ai-village' } }
// Link literature projects to the papers that name them: every alias of a project's name (split on " / ", " (", " — ", ", ") of four or more characters, matched case-insensitively in a paper's title, claim, or result.

