#!/usr/bin/env node
/**
 * Test driver: boot the experiment composition, run one frozen experiment over
 * the training-eligible environments with the composition's default route as
 * both arms, write the result to `./experiment.jsonl`, export every persisted
 * session to `./trajectories.jsonl`, and print the result for the e2e's
 * assertions.
 */

import { boot, resolveConfigPath } from '@deepseek-ai/dsh-app-boot'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import type {} from '@deepseek-ai/dsh-experiments'
import { jsonlFileSink } from '@deepseek-ai/dsh-trajectories'

const configPath = process.argv[2]
if (configPath === undefined) throw new Error('experiment driver requires a config path')

const ctx = await boot('experiment-e2e', resolveConfigPath(configPath, undefined))
try {
  // Loader siblings mount concurrently; the runner creates agents only over the settled application.
  await ctx.get('loader')?.await()
  const experiments = ctx.get('experiments')
  const environments = ctx.get('environments')
  const selection = ctx.get('agentDefaultModel')?.currentSelection()
  const trajectories = ctx.get('trajectories')
  if (experiments === undefined || environments === undefined || selection === undefined || trajectories === undefined) {
    throw new Error('experiment driver requires the experiments, environments, default-model, and trajectories services')
  }
  const route = { provider: selection.provider, model: selection.model }
  const result = await experiments.run({
    environments: environments.list({ heldOut: false }).map(definition => definition.id),
    repetitions: 2,
    baseline: route,
    candidate: route,
    workspaceRoot: process.cwd(),
    sink: jsonlFileSink('./experiment.jsonl'),
  })
  const exported = await trajectories.export({ sink: jsonlFileSink('./trajectories.jsonl') })
  process.stdout.write(`${JSON.stringify({ type: 'result', result, exported })}\n`)
} finally {
  await ctx.fiber.dispose()
}

/**
 * Producer: the live Proving Ground's environments — four small program
 * tasks, each a Node project whose own test suite is the standard and whose
 * tests are immutable; three are training-eligible and one is held out.
 */

import { fileURLToPath } from 'node:url'
import type { Context } from '@deepseek-ai/cordis'
import { EnvironmentId } from '@deepseek-ai/dsh-environments'
import type { EnvironmentDefinition } from '@deepseek-ai/dsh-environments'
import { CheckId } from '@deepseek-ai/dsh-verification'

declare module '@deepseek-ai/dsh-environments/types' {
  interface EnvironmentKindMap {
    /** A small program task in one language, verified by the fixture's own test suite. */
    code: { readonly language: string }
  }
}

export const name = 'register-environments'
export const inject = ['environments']

const OWNER = 'headless-agent village-live fixture'
const TESTS_PASS = CheckId('tests-pass')
const NO_DEPENDENCIES = CheckId('no-dependencies')

/** The rules every task shares: only `src/` changes, the tests and the manifest stay, nothing gets installed. */
const SHARED_RULES = 'Change only files under src/. Do not modify anything under test/ or package.json, and add no dependencies: node_modules must not exist. The standard is `node --test test/*.test.js` passing in the workspace root.'

/** A Node project task whose fixture's tests are the standard and may not be edited. */
function code(id: string, fixture: string, description: string, prompt: string, heldOut: boolean): EnvironmentDefinition<'code'> {
  return {
    id: EnvironmentId(id),
    kind: 'code',
    name: id,
    description,
    task: {
      prompt: `${prompt} ${SHARED_RULES}`,
      fixture: fileURLToPath(new URL(`./environments/${fixture}`, import.meta.url)),
      immutable: ['test', 'package.json'],
    },
    checks: [
      { id: TESTS_PASS, outcome: 'node --test test/*.test.js passes in the workspace root', run: 'node --test test/*.test.js' },
      { id: NO_DEPENDENCIES, outcome: 'no dependency was installed', run: 'test ! -e node_modules' },
    ],
    heldOut,
    owner: OWNER,
    provenance: 'curated',
    detail: { language: 'javascript' },
  }
}

/**
 * Register the four environments under the producer's own fiber.
 * @param ctx - the plugin context carrying the environment registry.
 */
export function apply(ctx: Context): void {
  const definitions = [
    code(
      'code:slugify',
      'slugify',
      'Implement a URL slug function against its test suite.',
      'Implement `slugify(input)` in `src/slugify.js`: lowercase the text, remove diacritics (NFD normalization, then drop the combining marks), replace every run of characters other than ASCII letters and digits with a single hyphen, trim leading and trailing hyphens, return an empty string when nothing remains, and throw a TypeError for a non-string argument.',
      false,
    ),
    code(
      'code:parse-duration',
      'parse-duration',
      'Implement a duration parser against its test suite.',
      'Implement `parseDuration(text)` in `src/duration.js`: a duration is a non-empty string of one to three components in the fixed order hours, minutes, seconds, each a non-negative integer immediately followed by `h`, `m`, or `s`, each unit at most once (`1h30m15s`, `2h`, `45m`, `90s`); return the total number of seconds as a number, and throw a TypeError for anything else, including a non-string, an empty string, whitespace, a sign, decimals, unknown units, repeated units, or units out of order.',
      false,
    ),
    code(
      'code:paginate-fix',
      'paginate-fix',
      'Fix a pagination function so its test suite passes.',
      '`src/paginate.js` is wrong and `node --test test/*.test.js` fails. Fix `paginate(items, page, size)` so pages are 1-based, `pages` is the number of pages needed to hold every item (0 for an empty list), pages past the last are empty, the input is never mutated, and a non-positive or fractional page or size throws a RangeError.',
      false,
    ),
    code(
      'code:csv-sum',
      'csv-sum',
      'Held out: sum one CSV column against its test suite.',
      'Implement `sumColumn(csv, column)` in `src/csv.js`: parse a comma-separated document whose first line is the header, find the named column, and return the sum of its numeric cells as a number; ignore empty cells and a missing trailing newline; return 0 when only the header is present; throw a RangeError for an unknown column, and a TypeError whose message names the offending data row as `row N` (counting data rows from 1) for a non-numeric cell.',
      true,
    ),
  ]
  for (const definition of definitions) ctx.effect(() => ctx.environments.register(definition))
}

#!/usr/bin/env node
/**
 * Driver: boot the village-live composition and keep its Proving Ground
 * district running on its cadence with the real Claude Code product as the
 * implementer of every cell. After the first slot, every refresh interval,
 * and at stop, it folds the observatory page and document, exports the
 * session facts and the trajectories, and writes `status.json` beside them.
 * `--once` runs the due slot, publishes, and stops, for the with-key e2e.
 */

import { writeFile } from 'node:fs/promises'
import { boot, resolveConfigPath } from '@deepseek-ai/dsh-app-boot'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import type {} from '@deepseek-ai/dsh-fleet'
import type {} from '@deepseek-ai/dsh-observatory'
import type {} from '@deepseek-ai/dsh-scorekeeper'
import type { SessionEvent } from '@deepseek-ai/dsh-session'
import type {} from '@deepseek-ai/dsh-shifts'
import { jsonlFileSink } from '@deepseek-ai/dsh-trajectories'

const configPath = process.argv[2]
if (configPath === undefined) throw new Error('village-live driver requires a config path')
const once = process.argv.includes('--once')
/** How often the running district republishes its page and exports. */
const REFRESH_MS = 300_000

const ctx = await boot('village-live', resolveConfigPath(configPath, undefined))
try {
  // Loader siblings mount concurrently; a slot freezes its plan against the
  // environment registry, so the driver drives only the settled application.
  await ctx.get('loader')?.await()
  const shifts = ctx.get('shifts')
  const observatory = ctx.get('observatory')
  const scorekeeper = ctx.get('scorekeeper')
  const trajectories = ctx.get('trajectories')
  const persistence = ctx.get('sessionPersistence')
  if (shifts === undefined || observatory === undefined || scorekeeper === undefined
    || trajectories === undefined || persistence === undefined) {
    throw new Error('village-live requires the shifts, observatory, scorekeeper, trajectories, and persistence services')
  }

  const publish = async (phase: string): Promise<void> => {
    const ledgers: { sessionId: string; cells: number; ended: boolean; outcome?: unknown }[] = []
    for (const stored of await persistence.list()) {
      const { events } = await persistence.inspect(stored.id)
      const shiftEvents = events.filter((event: SessionEvent) => event.type.startsWith('shift/'))
      if (shiftEvents.length === 0) continue
      const end = shiftEvents.find(event => event.type === 'shift/end')
      ledgers.push({
        sessionId: stored.id,
        cells: shiftEvents.filter(event => event.type === 'shift/cell').length,
        ended: end !== undefined,
        outcome: end === undefined ? undefined : (end.data as { outcome: unknown }).outcome,
      })
    }
    const snapshot = await observatory.snapshot()
    const page = observatory.render(snapshot, Date.now())
    await writeFile('observatory.html', page.html)
    await writeFile('observatory.json', `${JSON.stringify(page.json, null, 2)}\n`)
    const facts = await scorekeeper.exportFacts({ sink: jsonlFileSink('./facts.jsonl') })
    const exported = await trajectories.export({ sink: jsonlFileSink('./trajectories.jsonl') })
    const status = { type: 'status', phase, at: new Date().toISOString(), ledgers, rows: page.json.rows, facts, exported }
    await writeFile('status.json', `${JSON.stringify(status, null, 2)}\n`)
    process.stdout.write(`${JSON.stringify(status)}\n`)
  }

  const firstSlot = shifts.start()
  if (once) {
    await firstSlot
    await shifts.stop()
    await publish('once')
  } else {
    let settle: (() => void) | undefined
    const stopped = new Promise<void>((resolve) => { settle = resolve })
    const timer = setInterval(() => {
      publish('refresh').catch((error: unknown) => process.stderr.write(`${String(error)}\n`))
    }, REFRESH_MS)
    const onSignal = (): void => {
      clearInterval(timer)
      shifts.stop()
        .then(() => publish('stopped'))
        .catch((error: unknown) => process.stderr.write(`${String(error)}\n`))
        .finally(() => settle?.())
    }
    process.once('SIGTERM', onSignal)
    process.once('SIGINT', onSignal)
    await firstSlot
    await publish('first-slot')
    await stopped
  }
} finally {
  await ctx.fiber.dispose()
}

