// Direct SDK probe: same options as the route's claudeQueryOptions, printing
// every message the product emits, so the two-turn failure becomes visible.
//   node probe.mjs <label> [model] [effort|none] [maxTurns] [hint|none]
import { readFileSync } from 'node:fs'
import { query } from '/home/user/deepseek-harness/node_modules/.pnpm/@anthropic-ai+claude-agent-sdk@0.3.220_@anthropic-ai+sdk@0.93.0_zod@4.4.3__@modelcontex_57ba44dcbc2a36491e18d36fec520472/node_modules/@anthropic-ai/claude-agent-sdk/sdk.mjs'
import { renderRequest, RESPONSE_SCHEMA } from '/home/user/deepseek-harness/packages/llm/llm-claude-code/lib/index.js'

const here = new URL('.', import.meta.url).pathname
const [label = 'probe', model = 'sonnet', effortArg = 'medium', maxTurnsArg = '2', hint = 'none'] = process.argv.slice(2)
const system = readFileSync(`${here}system.txt`, 'utf8') + (hint === 'none' ? '' : `\n\n${hint}`)
const user = readFileSync(`${here}user.txt`, 'utf8')
const tools = JSON.parse(readFileSync(`${here}tools.json`, 'utf8'))
const rendered = renderRequest({
  model,
  system,
  messages: [{ role: 'user', content: [{ type: 'text', text: user }] }],
  tools,
})
const started = Date.now()
const q = query({
  prompt: rendered.prompt,
  options: {
    systemPrompt: rendered.systemPrompt,
    outputFormat: { type: 'json_schema', schema: RESPONSE_SCHEMA },
    includePartialMessages: false,
    maxTurns: Number(maxTurnsArg),
    permissionMode: 'dontAsk',
    tools: [],
    allowedTools: [],
    disallowedTools: ['AskUserQuestion'],
    mcpServers: {},
    strictMcpConfig: true,
    settingSources: [],
    persistSession: false,
    model,
    ...(effortArg === 'none' ? {} : { effort: effortArg }),
  },
})
const log = (...parts) => console.log(`[${label} +${((Date.now() - started) / 1000).toFixed(1)}s]`, ...parts)
try {
  for await (const message of q) {
    if (message.type === 'assistant') {
      const blocks = message.message.content.map((block) => {
        if (block.type === 'text') return `text(${block.text.length}): ${JSON.stringify(block.text.slice(0, 160))}`
        if (block.type === 'tool_use') return `tool_use ${block.name} ${JSON.stringify(block.input).slice(0, 200)}`
        if (block.type === 'thinking') return `thinking(${(block.thinking ?? '').length})`
        return block.type
      })
      log('assistant', `stop=${message.message.stop_reason}`, blocks.join(' | '))
    } else if (message.type === 'user') {
      const content = message.message.content
      const summary = Array.isArray(content)
        ? content.map(b => b.type === 'tool_result' ? `tool_result(${JSON.stringify(b.content).slice(0, 200)})` : `${b.type}:${JSON.stringify(b.text ?? '').slice(0, 200)}`).join(' | ')
        : JSON.stringify(content).slice(0, 200)
      log('user', summary)
    } else if (message.type === 'result') {
      log('result', message.subtype, `turns=${message.num_turns}`, `is_error=${message.is_error}`, `stop=${message.stop_reason ?? ''}`,
        `errors=${JSON.stringify(message.errors ?? [])}`,
        `structured=${JSON.stringify(message.structured_output ?? null).slice(0, 300)}`,
        `usage=${JSON.stringify(message.usage)}`)
    } else if (message.type === 'system' && message.subtype === 'init') {
      log('init', `model=${message.model}`, `tools=${JSON.stringify(message.tools)}`, `version=${message.claude_code_version ?? ''}`)
    } else {
      log(message.type, message.subtype ?? '')
    }
  }
  log('done')
} catch (error) {
  log('THROW', error instanceof Error ? error.message : String(error))
}

