// tools are offered as in-process MCP tools whose handlers only capture the
// call; maxTurns 1 ends the query after the first assistant message.
//   node probe-mcp.mjs <label> [model] [effort|none]
import { readFileSync } from 'node:fs'
import { query, tool, createSdkMcpServer } from '/home/user/deepseek-harness/node_modules/.pnpm/@anthropic-ai+claude-agent-sdk@0.3.220_@anthropic-ai+sdk@0.93.0_zod@4.4.3__@modelcontex_57ba44dcbc2a36491e18d36fec520472/node_modules/@anthropic-ai/claude-agent-sdk/sdk.mjs'
