#!/usr/bin/env node
/**
 * Test driver: boot the instrument-cases composition, run the registered
 * environment through the runner in a fixed `workspace/` directory, and stream
 * the run session's canonical events as JSONL so a snapshot can pin the
 * clustered directive the implementer sees. It exports the persisted sessions
 * to `./trajectories.jsonl` and ends with one `result` record naming the
 * session, its outcome, and the parity of every recorded run.
 */
import { mkdir } from 'node:fs/promises'
import { join } from 'node:path'
import { boot, resolveConfigPath } from '@deepseek-ai/dsh-app-boot'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import { EnvironmentId } from '@deepseek-ai/dsh-environments'
import type { SessionEvent } from '@deepseek-ai/dsh-session'
import { jsonlFileSink } from '@deepseek-ai/dsh-trajectories'
import type { RunParity } from '@deepseek-ai/dsh-verification'
const configPath = process.argv[2]
if (configPath === undefined) throw new Error('instrument-cases driver requires a config path')
const ctx = await boot('instrument-cases-e2e', resolveConfigPath(configPath, undefined))
try {
  // Loader siblings mount concurrently; the runner creates its agent only over the settled application.
  await ctx.get('loader')?.await()
  const runner = ctx.get('environmentRuns')
  const trajectories = ctx.get('trajectories')
  if (runner === undefined || trajectories === undefined) {
    throw new Error('instrument-cases driver requires the runner and the trajectories service')
  }
  // The runner mints its own session; every event of it is streamed from here,
  // so the transcript covers the run from its stamp to its last follow-up. The
  // parity of each attempt is durable, so it is collected from the run events.
  const parity: (RunParity | undefined)[] = []
  const stopStreaming = ctx.on('session/event', (session, event: SessionEvent) => {
    if (event.type === 'verification/run') parity.push(event.data.parity)
    process.stdout.write(`${JSON.stringify({ type: 'session_event', sessionId: session.id, event })}\n`)
  }, { global: true })
  const workspace = join(process.cwd(), 'workspace')
  await mkdir(workspace)
  const report = await runner.run({ environment: EnvironmentId('smoke:reverse-words'), workspace })
  stopStreaming()
  const exported = await trajectories.export({ sink: jsonlFileSink('./trajectories.jsonl') })
  process.stdout.write(`${JSON.stringify({
    type: 'result',
    sessionId: report.sessionId,
    certified: report.certified,
    parity,
    exported: exported.exported,
    rewarded: exported.rewarded,
  })}\n`)
} finally {
  await ctx.fiber.dispose()
}
== examples/headless-agent/tests/fixtures/instrument-cases/instrument-mock-llm.ts
/**
 * Keyless adapter that plays an implementer whose program reverses two of the
 * five sampled words, echoes one unreversed, answers one not at all, and fails
 * the last on stderr and its exit code: one bash call, a success report, then
 * one reply to the validation follow-up.
 */
import type { Context } from '@deepseek-ai/cordis'
import {
  CallId,
  LlmAdapter,
  type GenerateOptions,
  type LlmResolvedModelInfo,
  type StreamChunk,
} from '@deepseek-ai/dsh-llm'
/** The candidate program: correct for `ab` and `abc`, wrong on distinct channels for the rest. */
const WRITE_SOLVER = [
  "cat > solve.sh <<'SH'",
  'case "$1" in',
  "  ab) printf 'ba\\n' ;;",
  "  abc) printf 'cba\\n' ;;",
  "  xy) printf 'xy\\n' ;;",
  "  bad) printf 'oops\\n' >&2; exit 3 ;;",
  'esac',
  'SH',
].join('\n')
class InstrumentMockAdapter extends LlmAdapter {
  override async resolveModel(provider: string, model: string): Promise<LlmResolvedModelInfo> {
    return { provider, id: model, name: model }
  }
  async * stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const last = options.messages.at(-1)
    const text = (last?.content ?? []).flatMap(block => (block.type === 'text' ? [block.text] : [])).join('')
    if ((last?.content ?? []).some(block => block.type === 'tool-result')) {
      yield * reply('TASK COMPLETE')
      return
    }
    if (text.includes('<validation_failed>')) {
      yield * reply('STOPPED')
      return
    }
    const args = JSON.stringify({ command: WRITE_SOLVER, description: 'Write the solver script.' })
    yield { type: 'block-start', index: 0, blockType: 'tool-call' }
    yield { type: 'tool-call-delta', index: 0, id: CallId('solver-call'), name: 'bash', argumentsDelta: args }
    yield { type: 'block-end', index: 0, block: { type: 'tool-call', id: CallId('solver-call'), name: 'bash', arguments: args } }
    yield { type: 'usage', usage: { inputTokens: 17, outputTokens: 9 } }
    yield { type: 'finish', reason: { kind: 'tool-calls' } }
  }
}
/** One text answer as the canonical block sequence of a stopped step. */
function * reply(text: string): Generator<StreamChunk> {
  yield { type: 'block-start', index: 0, blockType: 'text' }
  yield { type: 'text-delta', index: 0, text }
  yield { type: 'block-end', index: 0, block: { type: 'text', text } }
  yield { type: 'usage', usage: { inputTokens: 23, outputTokens: 2 } }
  yield { type: 'finish', reason: { kind: 'stop' } }
}
export const name = 'instrument-mock-llm'
export const inject = ['llm']
/**
 * Register the keyless `instrument-mock` adapter.
 * @param ctx - the plugin context carrying the LLM runtime.
 */
export function apply(ctx: Context): void {
  ctx.llm.registerAdapter(['instrument-mock'], new InstrumentMockAdapter())
}
== examples/headless-agent/tests/fixtures/instrument-cases/register-environment.ts
/** Test-only producer: one environment whose single check carries five weighted cases over four channels. */
import type { Context } from '@deepseek-ai/cordis'
import { EnvironmentId } from '@deepseek-ai/dsh-environments'
import type { EnvironmentDefinition } from '@deepseek-ai/dsh-environments'
import { caseChannelDigest, CheckCaseId, checkCasesRef, CheckId } from '@deepseek-ai/dsh-verification'
import type { CheckCase } from '@deepseek-ai/dsh-verification'
declare module '@deepseek-ai/dsh-environments/types' {
  interface EnvironmentKindMap {
    /** A keyless task whose check is sampled case by case; no kind-specific detail. */
    'instrument-smoke': Record<string, never>
  }
}
export const name = 'register-environment'
export const inject = ['environments']
/** SHA-256 of one expected stream after the comparator's `crlf` normalizer. */
const expect = (text: string): string => caseChannelDigest(Buffer.from(text, 'utf8'), ['crlf'])
/** One case comparing the candidate's stdout and exit code for one input word. */
function reverses(id: string, word: string, reversed: string, weight: number): CheckCase {
  return {
    id: CheckCaseId(id),
    weight,
    input: { argv: [word] },
    expected: { exitCode: 0, stdoutSha256: expect(`${reversed}\n`) },
    comparator: { channels: ['exit', 'stdout'], normalizers: ['crlf'] },
  }
}
const cases: readonly CheckCase[] = [
  reverses('reverse-ab', 'ab', 'ba', 1),
  reverses('reverse-abc', 'abc', 'cba', 2),
  reverses('reverse-xy', 'xy', 'yx', 3),
  reverses('reverse-zw', 'zw', 'wz', 4),
  {
    id: CheckCaseId('reverse-bad'),
    weight: 5,
    input: { argv: ['bad'] },
    expected: { exitCode: 0, stderrSha256: expect('') },
    comparator: { channels: ['exit', 'stderr'], normalizers: ['crlf'] },
  },
]
const definition: EnvironmentDefinition<'instrument-smoke'> = {
  id: EnvironmentId('smoke:reverse-words'),
  kind: 'instrument-smoke',
  name: 'smoke:reverse-words',
  description: 'solve.sh prints its argument reversed and reports nothing on stderr.',
  task: {
    prompt: 'Write solve.sh in the workspace so that `sh solve.sh WORD` prints WORD reversed on stdout, writes nothing to stderr, and exits 0.',
  },
  checks: [{
    id: CheckId('reverses-words'),
    outcome: 'solve.sh prints its argument reversed and reports nothing on stderr',
    run: 'sh solve.sh',
    cases: checkCasesRef(cases),
    caseBodies: cases,
  }],
  heldOut: false,
  owner: 'headless-agent instrument-cases fixture',
  provenance: 'curated',
  detail: {},
}
/**
 * Register the environment under the producer's own fiber.
 * @param ctx - the plugin context carrying the environment registry.
 */
export function apply(ctx: Context): void {
  ctx.effect(() => ctx.environments.register(definition))
}

