// Per-cell and per-arm summary of one bench run directory (fleet or experiment):
//   node analyze-run.mjs <run dir> [--rows]
// Reads every cell session log under <run dir>/.sessions and prints, per arm
// (implementer), the certificate count, attempts, wall time quantiles, and for
// route cells the summed token usage; for delegated cells the reported usage
// and cost when the delegation event carries them.
import { readdirSync, readFileSync, statSync } from 'node:fs'
import { join } from 'node:path'

const [root, ...flags] = process.argv.slice(2)
if (!root) throw new Error('usage: analyze-run.mjs <run dir> [--rows]')
const showRows = flags.includes('--rows')

function* sessionLogs(dir) {
  for (const entry of readdirSync(dir)) {
    const path = join(dir, entry)
    if (statSync(path).isDirectory()) yield* sessionLogs(path)
    else if (entry === 'session.jsonl') yield path
  }
}

const cells = []
for (const file of sessionLogs(join(root, '.sessions'))) {
  const events = readFileSync(file, 'utf8').trim().split('\n').map(line => JSON.parse(line))
  const run = events.find(e => e.type === 'environment/run')
  if (!run) continue
  const cert = events.find(e => e.type === 'verification/certificate')
  const last = events[events.length - 1]
  const validations = events.filter(e => e.type === 'verification/run')
  const delegations = events.filter(e => e.type === 'environment/delegation')
  const usage = events.filter(e => e.type === 'assistant/chunk' && e.data.chunk.type === 'usage').map(e => e.data.chunk.usage)
  const sum = key => usage.reduce((a, u) => a + (u[key] ?? 0), 0)
  const reported = delegations.map(d => d.data.reportedUsage).filter(Boolean)
  const reportedSum = key => reported.reduce((a, u) => a + (u[key] ?? 0), 0)
  cells.push({
    env: run.data.environmentId,
    rep: run.data.repetition,
    arm: run.data.implementer ?? 'route',
    model: `${run.data.model.provider}/${run.data.model.model}`,
    reportedModel: delegations.map(d => d.data.reportedModel).filter(Boolean)[0],
