  console.log(JSON.stringify({ paired: pairs.length, fasterWins: wins, wallTimeRatio: `${a}/${b}=${ratio}`, certificateFlips: pairs.filter(p => p.certA !== p.certB).length }))
  if (showRows) for (const p of pairs) console.log(JSON.stringify(p))
}

